SourceCode.Declaration:
/// <summary>
/// pickup advice report controller
/// </summary>
internal final class METPickupAdviceReportController extends SRSReportRunController
{
}

Method.Source:
/// <summary>Constuct new object</summary>
/// <param name = "_args">Arguments</param>
/// <returns>New Controller Object</returns>
public static METPickupAdviceReportController construct(Args _args)
{
    METPickupAdviceReportController controller = new METPickupAdviceReportController();
    controller.parmArgs(_args);
    controller.parmReportName(ssrsReportStr(METPickUpAdvicesReport, Report));
    controller.parmShowDialog(false);

    return controller;
}

/// <summary>
/// The main method of the batch job.
/// </summary>
/// <param name = "_args">The arguments passed by the caller object.</param>
public static void main(Args _args)
{
    SysOperationController          controller      = METPickupAdviceReportController::construct(_args);
    container                       conShipmentId   = str2con(_args.parm());
    METPickupAdviceReportContract   contract;

    for(int i =1; conLen(conShipmentId) >= i; i++)
    {
        contract = controller.getDataContractObject() as METPickupAdviceReportContract;
        contract.parmShipmentID(conPeek(conShipmentId, i));

        controller.startOperation();
    }
}
